create or replace package body t010_finance_pkg as
  function payment(p_principal in number, p_annual_pct in number, p_months in number)
    return number is
    l_monthly_rate number;
  begin
    if p_annual_pct = 0 then
      l_monthly_rate := 0;
    else
      l_monthly_rate := p_annual_pct / 1200;
    end if;

    if l_monthly_rate = 0 then
      -- For interest-free loans, the payment is simply principal / months
      return round(p_principal / p_months, 2);
    else
      return round(p_principal * t010_math.annuity_factor(p_months, l_monthly_rate), 2);
    end if;
  end payment;
end t010_finance_pkg;
/
